<script setup lang="ts">
import { computed } from 'vue';
import { Head, Link, usePage } from '@inertiajs/vue3';
import { ArrowLeft, RefreshCw, ShieldCheck, ClipboardList, Clock, FileText, MessageSquare, Paperclip } from '@lucide/vue';
import AuthenticatedLayout from '@/Layouts/AuthenticatedLayout.vue';
import OptionSelect from '@/Components/UI/OptionSelect.vue';
import { MDT_NOTE_CATEGORIES } from '@/utils/caseOptions';
import { formatPh, parseStored } from '@/utils/philippineTime';
import { useMdtWorkspace } from '@/composables/useMdtWorkspace';
import type { PageProps } from '@/types';

const props = defineProps<{ caseId: number; assignmentId: number }>();
const page = usePage<PageProps>();
const work = useMdtWorkspace(props.caseId, props.assignmentId);
const { data, thread, assignment, loading, saving, busy, locked, denied, error, errorBox, errors, notice, uncertain, reviewed, dirty,
    message, file, fileKey, note, attachment, addendumFor, addendumReason } = work;
const human = (value?: string | null) => value ? value.replaceAll('_', ' ').replace(/^\w/, letter => letter.toUpperCase()) : 'Not recorded';
const date = (value?: string | null) => value ? formatPh(value, 'dateTime') : 'Not specified';
const overdue = (value?: string | null) => Boolean(value && (parseStored(value)?.getTime() ?? Infinity) < Date.now());
const pending = computed(() => data.value?.actions.filter(item => !['responded', 'completed'].includes(item.status)).length ?? 0);
function choose(event: Event) {
    const field = event.target as HTMLSelectElement;
    const id = Number(field.value); field.value = String(assignment.value); void work.choose(id);
}
</script>

<template>
  <Head title="My referred case" />
  <AuthenticatedLayout>
    <section class="mx-auto w-full max-w-6xl space-y-5 pb-6">
      <div class="flex flex-wrap items-center justify-between gap-3">
        <Link :href="route('mdt.collaboration.index')" class="inline-flex min-h-11 items-center gap-2 text-sm font-semibold text-brand-800"><ArrowLeft class="h-4 w-4" aria-hidden="true" />My referred cases</Link>
        <button type="button" :disabled="busy" class="ui-button gap-2" @click="work.load"><RefreshCw class="h-4 w-4" :class="loading ? 'animate-spin' : ''" aria-hidden="true" />Refresh assignment</button>
      </div>
      <header class="rounded-xl border border-slate-200 bg-white p-5 sm:p-6">
        <p class="text-xs font-semibold uppercase tracking-wide text-brand-800">Your CPU assignment</p>
        <h1 class="mt-2 break-words text-2xl font-bold text-slate-900">{{ data?.case_number ?? (denied ? 'Assignment unavailable' : 'Loading assignment') }}</h1>
        <p class="mt-2 flex items-start gap-2 text-sm leading-6 text-slate-600"><ShieldCheck class="mt-1 h-4 w-4 shrink-0 text-brand-700" aria-hidden="true" />This workspace shows your referral and permitted case information. LGU group membership does not provide access to other cases.</p>
      </header>
      <div v-if="error" ref="errorBox" role="alert" tabindex="-1" class="rounded-lg border border-rose-200 bg-rose-50 p-4 text-sm text-rose-900"><p class="font-semibold">{{ error }}</p><ul v-if="Object.keys(errors).length" class="mt-2 list-inside list-disc"><li v-for="(text, key) in errors" :key="key">{{ human(String(key)) }}: {{ text }}</li></ul></div>
      <p v-if="notice" role="status" class="rounded-lg bg-emerald-50 p-3 text-sm text-emerald-900">{{ notice }}</p>
      <div v-if="uncertain && !denied" class="flex flex-wrap items-center gap-3 rounded-lg border border-amber-300 bg-amber-50 p-4 text-sm text-amber-950"><p class="min-w-0 flex-1">Writes are paused until you refresh and review the last save. No automatic retry will be made.</p><button type="button" class="ui-button" :disabled="busy || !reviewed" @click="work.resolveUncertainty">I reviewed the saved records</button></div>
      <div v-if="dirty && !denied" class="flex flex-wrap items-center justify-between gap-3 text-sm text-slate-600"><p>Unsent entries remain in this tab. Save them before changing assignments or completing an action.</p><button type="button" class="ui-button" :disabled="busy" @click="work.discard">Discard unsaved entries</button></div>
      <p v-if="loading" role="status" class="text-sm text-slate-600">Checking your current assignment and access...</p>

      <template v-if="data && !denied">
        <div v-if="data.assignments.length > 1" class="rounded-xl border border-amber-200 bg-amber-50 p-4"><label for="mdt-assignment" class="text-sm font-semibold text-slate-900">Active assignment for this case</label><p id="assignment-hint" class="mt-1 text-sm text-slate-700">You have {{ data.assignments.length }} active assignments for this case. Each has its own instructions, actions, notes and files.</p><select id="mdt-assignment" :value="assignment" :disabled="busy || uncertain" aria-describedby="assignment-hint" class="ui-field mt-3 w-full" @change="choose"><option v-for="item in data.assignments" :key="item.id" :value="item.id">#{{ item.id }} - {{ item.purpose }} - {{ item.pending_actions }} pending</option></select></div>

        <section aria-labelledby="referral-heading" class="rounded-xl border border-slate-200 bg-white p-5 sm:p-6">
          <div class="flex flex-wrap items-start justify-between gap-3"><div><p class="text-xs font-semibold text-slate-600">Assignment #{{ data.grant.id }}</p><h2 id="referral-heading" class="mt-1 text-lg font-semibold text-slate-900">Why this case was referred to you</h2></div><span class="rounded-md bg-brand-50 px-3 py-2 text-sm font-semibold text-brand-900">Assignment status: {{ human(data.grant.status) }}</span></div>
          <p class="mt-4 whitespace-pre-wrap break-words text-base leading-7 text-slate-900">{{ data.grant.purpose || 'No referral purpose recorded. Ask the referring case manager for clarification.' }}</p>
          <div v-if="data.grant.remarks" class="mt-4 rounded-lg bg-slate-50 p-4"><h3 class="text-sm font-semibold text-slate-900">Referral note</h3><p class="mt-2 whitespace-pre-wrap break-words text-sm leading-6 text-slate-700">{{ data.grant.remarks }}</p></div>
          <dl class="mt-5 grid gap-4 border-t border-slate-100 pt-4 text-sm sm:grid-cols-2 lg:grid-cols-4"><div><dt class="text-slate-600">Referred by</dt><dd class="mt-1 font-medium text-slate-900">{{ data.referrer?.name ?? 'Not recorded' }}</dd></div><div><dt class="text-slate-600">Your role / office</dt><dd class="mt-1 break-words font-medium text-slate-900">{{ data.grant.professional_role }}<span class="block font-normal text-slate-600">{{ data.grant.organization }}</span></dd></div><div><dt class="text-slate-600">Assigned</dt><dd class="mt-1 text-slate-900">{{ date(data.grant.assigned_at) }}</dd></div><div><dt class="text-slate-600">Access ends (Philippine time)</dt><dd class="mt-1 text-slate-900">{{ date(data.grant.access_expires_at) }}</dd></div></dl>
          <button v-if="data.grant.status === 'assigned' && !data.grant.acknowledged_at" type="button" class="ui-button ui-button-primary mt-5" :disabled="locked" @click="work.acknowledge">Acknowledge receipt</button>
        </section>

        <section aria-labelledby="actions-heading" class="rounded-xl border border-slate-200 bg-white p-5 sm:p-6">
          <div class="flex flex-wrap items-center justify-between gap-3"><h2 id="actions-heading" class="flex items-center gap-2 text-lg font-semibold text-slate-900"><ClipboardList class="h-5 w-5 text-brand-700" aria-hidden="true" />What you need to do</h2><span class="text-sm text-slate-600">{{ pending }} awaiting response</span></div>
          <div v-if="!data.actions.length" class="mt-4 rounded-lg border border-dashed border-slate-300 p-4 text-sm leading-6 text-slate-600">No separate action has been recorded for this assignment. Review the referral purpose above and ask the case manager to clarify the requested work. Other active assignments can be selected above.</div>
          <article v-for="item in data.actions" :key="item.id" class="mt-4 rounded-lg border border-slate-200 p-4"><div class="flex flex-wrap items-start justify-between gap-3"><h3 class="min-w-0 flex-1 break-words font-semibold text-slate-900">{{ item.title }}</h3><span class="rounded-md bg-slate-100 px-2 py-1 text-xs font-semibold text-slate-700">{{ human(item.status) }}</span></div><p class="mt-3 whitespace-pre-wrap break-words text-sm leading-6 text-slate-700">{{ item.instructions || 'No detailed instructions recorded. Ask the case manager if the requested action is unclear.' }}</p><p class="mt-3 flex items-start gap-2 text-sm" :class="overdue(item.due_at) && item.status !== 'completed' ? 'font-semibold text-rose-800' : 'text-slate-600'"><Clock class="mt-0.5 h-4 w-4 shrink-0" aria-hidden="true" />Due: {{ date(item.due_at) }}{{ overdue(item.due_at) && item.status !== 'completed' ? ' - overdue' : '' }}</p><p v-if="item.responded_at" class="mt-1 text-xs text-slate-600">Response recorded: {{ date(item.responded_at) }}</p><div v-if="item.status !== 'completed'" class="mt-4 flex flex-wrap gap-2"><button v-if="item.status !== 'responded'" type="button" class="ui-button" :disabled="locked" @click="work.respond(item.id, 'responded')">Mark responded</button><button type="button" class="ui-button ui-button-primary" :disabled="locked" @click="work.respond(item.id, 'completed')">Mark complete</button></div></article>
          <p v-if="data.actions.length" class="mt-4 text-xs leading-5 text-slate-600">Save your notes and supporting files before completing an action. Completion ends active access under the current assignment workflow.</p>
        </section>

        <section aria-labelledby="context-heading" class="rounded-xl border border-slate-200 bg-white p-5 sm:p-6">
          <h2 id="context-heading" class="text-lg font-semibold text-slate-900">Case context shared with you</h2><p class="mt-1 text-sm leading-6 text-slate-600">Only the categories authorized for this assignment are included. This is not the full client record.</p>
          <dl class="mt-4 grid gap-4 text-sm sm:grid-cols-2 lg:grid-cols-4"><div><dt class="text-slate-600">Case status</dt><dd class="mt-1 font-medium text-slate-900">{{ human(data.status) }}</dd></div><div><dt class="text-slate-600">Case stage</dt><dd class="mt-1 font-medium text-slate-900">{{ human(data.stage) }}</dd></div><template v-if="data.summary"><div><dt class="text-slate-600">Category</dt><dd class="mt-1 font-medium text-slate-900">{{ data.summary.category || 'Not recorded' }}</dd></div><div><dt class="text-slate-600">Priority</dt><dd class="mt-1 font-medium text-slate-900">{{ human(data.summary.priority) }}</dd></div><div><dt class="text-slate-600">Case opened</dt><dd class="mt-1 text-slate-900">{{ date(data.summary.opened_at) }}</dd></div></template></dl>
          <div v-if="data.plans" class="mt-5 border-t border-slate-100 pt-4"><h3 class="text-sm font-semibold text-slate-900">Shared case plans</h3><article v-for="plan in data.plans" :key="plan.id" class="mt-3 rounded-lg bg-slate-50 p-3 text-sm"><p class="whitespace-pre-wrap break-words leading-6 text-slate-700">{{ plan.summary || 'No plan summary recorded.' }}</p><p class="mt-2 text-xs text-slate-600">{{ human(plan.status) }} - Review: {{ date(plan.review_due_at) }}</p></article><p v-if="!data.plans.length" class="mt-2 text-sm text-slate-600">No case plan recorded.</p></div>
          <div v-if="data.referrals" class="mt-5 border-t border-slate-100 pt-4"><h3 class="text-sm font-semibold text-slate-900">Shared service referrals</h3><article v-for="referral in data.referrals" :key="referral.id" class="mt-3 rounded-lg bg-slate-50 p-3 text-sm"><p class="font-medium text-slate-900">{{ referral.service_category || 'Service referral' }}</p><p class="mt-1 text-slate-600">{{ human(referral.status) }} - {{ date(referral.referred_at) }}</p></article><p v-if="!data.referrals.length" class="mt-2 text-sm text-slate-600">No service referral recorded.</p></div>
          <p v-if="!data.summary && !data.plans && !data.referrals" class="mt-4 text-sm text-slate-600">No additional case-summary, plan or service-referral category was authorized for this assignment.</p>
        </section>

        <section aria-labelledby="notes-heading" class="rounded-xl border border-slate-200 bg-white p-5 sm:p-6">
          <h2 id="notes-heading" class="flex items-center gap-2 text-lg font-semibold text-slate-900"><FileText class="h-5 w-5 text-brand-700" aria-hidden="true" />Your findings and recommendation</h2><p class="mt-1 text-sm leading-6 text-slate-600">Notes belong to the selected assignment. Final notes are immutable; corrections use a linked addendum.</p>
          <article v-for="item in data.notes" :key="item.id" class="mt-4 rounded-lg border border-slate-200 p-4"><div class="flex flex-wrap items-center justify-between gap-2"><h3 class="break-words font-semibold text-slate-900">{{ item.category }}</h3><span class="text-xs font-semibold text-slate-700">{{ human(item.status) }}</span></div><p v-if="item.previous_note_id" class="mt-2 text-xs text-slate-600">Addendum to note #{{ item.previous_note_id }}: {{ item.addendum_reason }}</p><dl class="mt-3 space-y-3 text-sm"><div><dt class="font-medium text-slate-900">Findings</dt><dd class="mt-1 whitespace-pre-wrap break-words leading-6 text-slate-700">{{ item.findings || 'Not recorded' }}</dd></div><div><dt class="font-medium text-slate-900">Recommendation</dt><dd class="mt-1 whitespace-pre-wrap break-words leading-6 text-slate-700">{{ item.recommendation || 'Not recorded' }}</dd></div></dl><p class="mt-3 text-xs text-slate-600">{{ item.finalized_at ? 'Finalized' : 'Created' }}: {{ date(item.finalized_at || item.created_at) }}</p><div class="mt-3 flex flex-wrap gap-2"><button v-if="item.status === 'draft' && item.created_by === page.props.auth.user.id" type="button" class="ui-button" :disabled="locked" @click="work.finalize(item)">Finalize note</button><button v-if="item.status === 'final'" type="button" class="ui-button" :disabled="locked" @click="work.startAddendum(item)">Add addendum</button></div></article>
          <form class="mt-5 border-t border-slate-100 pt-5" @submit.prevent="work.saveNote"><fieldset :disabled="locked" class="space-y-4"><legend class="mb-3 text-sm font-semibold text-slate-900">{{ addendumFor ? `Addendum to note #${addendumFor.id}` : 'Record a professional note' }}</legend><label v-if="addendumFor" class="block text-sm font-medium text-slate-800">Reason for addendum<textarea v-model="addendumReason" required maxlength="2000" rows="2" class="ui-field mt-2" /></label><div><label for="mdt-note-category" class="block text-sm font-medium text-slate-800">Note category</label><OptionSelect id="mdt-note-category" v-model="note.category" class="mt-2" :options="MDT_NOTE_CATEGORIES" required :disabled="locked" :invalid="Boolean(errors.category)" /></div><label class="block text-sm font-medium text-slate-800">Findings<textarea v-model="note.findings" maxlength="5000" rows="3" class="ui-field mt-2" /></label><label class="block text-sm font-medium text-slate-800">Recommendation<textarea v-model="note.recommendation" maxlength="5000" rows="3" class="ui-field mt-2" /></label><div class="flex flex-wrap gap-2"><button type="submit" class="ui-button ui-button-primary">{{ saving ? 'Saving...' : addendumFor ? 'Save final addendum' : 'Save draft note' }}</button><button v-if="addendumFor" type="button" class="ui-button" @click="work.cancelAddendum">Cancel addendum</button></div></fieldset></form>
        </section>

        <section aria-labelledby="files-heading" class="rounded-xl border border-slate-200 bg-white p-5 sm:p-6">
          <h2 id="files-heading" class="flex items-center gap-2 text-lg font-semibold text-slate-900"><Paperclip class="h-5 w-5 text-brand-700" aria-hidden="true" />Supporting files for this assignment</h2><p class="mt-1 text-sm leading-6 text-slate-600">Only files shared under this assignment appear here. New files remain unavailable until scan clearance.</p>
          <article v-for="item in data.attachments" :key="item.id" class="mt-3 flex flex-wrap items-center justify-between gap-3 rounded-lg border border-slate-200 p-3"><div class="min-w-0"><h3 class="break-words text-sm font-semibold text-slate-900">{{ item.name }}</h3><p class="mt-1 text-xs text-slate-600">{{ human(item.purpose_category) }} - {{ Math.ceil(item.size_bytes / 1024) }} KB - {{ human(item.scan_state) }}</p></div><a v-if="item.scan_state === 'cleared'" :href="work.download(item.id)" class="ui-button text-sm">Download authorized file</a><span v-else class="text-xs font-semibold text-amber-900">Awaiting scan clearance</span></article><p v-if="!data.attachments.length" class="mt-3 text-sm text-slate-600">No file shared under this assignment.</p>
          <form class="mt-5 border-t border-slate-100 pt-5" @submit.prevent="work.upload"><fieldset :disabled="locked" class="grid gap-4 sm:grid-cols-2"><legend class="mb-3 text-sm font-semibold text-slate-900">Add a supporting file</legend><label class="block min-w-0 text-sm font-medium text-slate-800">File<input :key="fileKey" required type="file" accept="application/pdf,image/jpeg,image/png,.doc,.docx" class="mt-2 block min-h-11 w-full min-w-0 max-w-full text-sm" @change="file = ($event.target as HTMLInputElement).files?.[0] ?? null" /><span class="mt-1 block text-xs leading-5 text-slate-600">PDF, JPG, PNG, DOC or DOCX. Maximum 10 MB.</span></label><label class="block text-sm font-medium text-slate-800">File purpose<select v-model="attachment.purpose_category" class="ui-field mt-2"><option value="supporting_record">Supporting record</option><option value="service_response">Service response</option><option value="professional_observation">Professional observation</option></select></label><label class="block text-sm font-medium text-slate-800">Related action<select v-model="attachment.mdt_action_id" class="ui-field mt-2"><option value="">None</option><option v-for="item in data.actions" :key="item.id" :value="String(item.id)">{{ item.title }}</option></select></label><label class="block text-sm font-medium text-slate-800">Related note<select v-model="attachment.mdt_note_id" class="ui-field mt-2"><option value="">None</option><option v-for="item in data.notes" :key="item.id" :value="String(item.id)">{{ item.category }} #{{ item.id }}</option></select></label><button type="submit" class="ui-button ui-button-primary w-fit">Upload authorized file</button></fieldset></form>
        </section>

        <details class="rounded-xl border border-slate-200 bg-white p-5 sm:p-6"><summary class="flex min-h-11 cursor-pointer items-center gap-2 text-base font-semibold text-slate-900"><MessageSquare class="h-5 w-5 text-brand-700" aria-hidden="true" />Case coordination discussion ({{ thread.length }})</summary><p class="mt-3 text-sm leading-6 text-slate-600">Coordination with the case manager and CPU members who have active access to this case. This is separate from the LGU group chat and formal notes.</p><article v-for="item in thread" :key="item.id" class="mt-3 rounded-lg bg-slate-50 p-4"><p class="text-sm font-semibold text-slate-900">{{ item.author }}<time class="ml-2 text-xs font-normal text-slate-600">{{ date(item.created_at) }}</time></p><p class="mt-2 whitespace-pre-wrap break-words text-sm leading-6 text-slate-700">{{ item.body }}</p></article><form class="mt-4" @submit.prevent="work.post"><fieldset :disabled="locked"><label for="mdt-discussion" class="text-sm font-medium text-slate-800">Coordination message</label><textarea id="mdt-discussion" v-model="message" required maxlength="3000" rows="3" class="ui-field mt-2" /><button type="submit" class="ui-button mt-3">Post message</button></fieldset></form></details>
      </template>
    </section>
  </AuthenticatedLayout>
</template>


